formal.sva:
// 本断言尝试捕捉重播种请求被阻塞的场景；由于内部“需要重播种”条件未知，仅为示意性性质
// 当掩码使能且 prng_reseed_done_q 为 0 时，若 prng_reseed_q_i 长时间为 0，则 prng_reseed_req_o 也应被阻塞，但这可能导致安全缺口
// 期望的性质为：need_reseed_condition |-> eventually prng_reseed_req_o，但 need_reseed_condition 未知
// 因此给出部分可形式化版本：在掩码使能且 reseed 未完成时，prng_reseed_q_i 必须最终为 1 以满足重播种请求
// 真实模块中该条件依赖外部输入，故性质 formalizability 有限
property prng_reseed_gap;
  @(posedge clk_i) disable iff (!rst_ni)
  (SecMasking && !prng_reseed_done_q) |-> ##[0:$] prng_reseed_q_i;
endproperty
